/* eslint-disable @next/next/no-img-element */
"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import Link from "next/link";
import { AlertTriangle, ArrowDown, ArrowLeft, ArrowUp, Camera, CheckCircle2, Clock3, Edit3, Grip, History, ImagePlus, LayoutGrid, List, Loader2, MapPin, MoreHorizontal, PackagePlus, Plus, QrCode, RotateCcw, ScanLine, Search, Settings, Trash2, UserRound, Wrench, X } from "lucide-react";
import BarcodeScanner from "@/components/almacen-desguace/BarcodeScanner";
import { ShelfLocationLabelsButton, ToolQrLabelButton } from "@/components/herramientas-comunes/CommonToolLabels";
import { parseCommonToolsQr } from "@/lib/herramientas-comunes-qr";
import { PHOTO_SOURCE_MAX_BYTES } from "@/lib/photo-upload";
import { optimizePhoto } from "@/lib/photo-upload-client";
import type { AppUser } from "@/lib/app-users";
import { ActionActorSelect, useActionActors } from "@/components/auth/ActionActorSelect";
import { DEFAULT_TOOL_SETTINGS, type ToolSettings } from "@/lib/app-settings";
import type { ConfiguracionEstanteriaHerramientas, EstadoHerramienta, EstanteriaHerramientas, FilaEstanteriaHerramientas, HerramientaComun, MovimientoHerramienta } from "@/types/herramientas-comunes";

type Data = { shelves: EstanteriaHerramientas[]; tools: HerramientaComun[]; movements: MovimientoHerramienta[]; settings: ToolSettings };
type ScannedLocation = { shelf: EstanteriaHerramientas; level: number; position: string };
const EMPTY_DATA: Data = { shelves: [], tools: [], movements: [], settings: DEFAULT_TOOL_SETTINGS };
const STATUS: Record<EstadoHerramienta, { label: string; classes: string }> = {
  disponible: { label: "Disponible", classes: "border-emerald-500/30 bg-emerald-500/10 text-emerald-300" },
  prestada: { label: "Prestada", classes: "border-amber-500/30 bg-amber-500/10 text-amber-300" },
  reparacion: { label: "No localizada", classes: "border-red-500/30 bg-red-500/10 text-red-300" },
  perdida: { label: "No localizada", classes: "border-red-500/30 bg-red-500/10 text-red-300" },
};

export default function CommonToolsPage() {
  const [data, setData] = useState<Data>(EMPTY_DATA);
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const { users: actionUsers, loading: actionUsersLoading } = useActionActors(currentUser);
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<EstadoHerramienta | "">("");
  const [view, setView] = useState<"lista" | "estanterias" | "prestamos">("lista");
  const [mobileTab, setMobileTab] = useState<"buscar" | "lista" | "prestamos" | "plano" | "mas">("buscar");
  const searchInput = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(true);
  const [setupRequired, setSetupRequired] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [creating, setCreating] = useState(false);
  const [managingShelves, setManagingShelves] = useState(false);
  const [loanTool, setLoanTool] = useState<HerramientaComun | null>(null);
  const [historyTool, setHistoryTool] = useState<HerramientaComun | null>(null);
  const [locationTool, setLocationTool] = useState<HerramientaComun | null>(null);
  const [editingTool, setEditingTool] = useState<HerramientaComun | null>(null);
  const [scannedTool, setScannedTool] = useState<HerramientaComun | null>(null);
  const [scannedLocation, setScannedLocation] = useState<ScannedLocation | null>(null);
  const [scannerMode, setScannerMode] = useState<"general" | "return-location" | "assign-location" | null>(null);
  const [returningTool, setReturningTool] = useState<HerramientaComun | null>(null);
  const [placingTool, setPlacingTool] = useState<HerramientaComun | null>(null);
  const [planTool, setPlanTool] = useState<HerramientaComun | null>(null);
  const [unlocatedOpen, setUnlocatedOpen] = useState(false);
  const [labelsOpen, setLabelsOpen] = useState(false);
  const [labelTool, setLabelTool] = useState<HerramientaComun | null>(null);
  const [photoPreview, setPhotoPreview] = useState<{ url: string; alt: string } | null>(null);
  const [busyId, setBusyId] = useState<number | null>(null);
  const handledInitialQr = useRef(false);
  const backgroundRefreshInFlight = useRef(false);

  const load = useCallback(async ({ silent = false }: { silent?: boolean } = {}) => {
    if (silent && backgroundRefreshInFlight.current) return;
    if (silent) backgroundRefreshInFlight.current = true;
    else setLoading(true);
    try {
      const [response, settingsResponse] = await Promise.all([fetch("/api/herramientas-comunes", { cache: "no-store" }), fetch("/api/configuracion/herramientas", { cache: "no-store" })]);
      const payload = await response.json() as Data & { error?: string; setupRequired?: boolean };
      const settingsPayload = await settingsResponse.json().catch(() => ({})) as { settings?: ToolSettings };
      payload.settings = settingsPayload.settings || DEFAULT_TOOL_SETTINGS;
      setSetupRequired(Boolean(payload.setupRequired));
      if (!response.ok) throw new Error(payload.error || "No se pudieron cargar las herramientas.");
      setData(payload);
      setError(""); setSetupRequired(false);
      return payload;
    } catch (caught) {
      if (!silent) setError(caught instanceof Error ? caught.message : "No se pudieron cargar las herramientas.");
    } finally {
      if (silent) backgroundRefreshInFlight.current = false;
      else setLoading(false);
    }
  }, []);

  useEffect(() => { void Promise.resolve().then(() => load()); }, [load]);
  useEffect(() => {
    const refreshWhenActive = () => {
      if (document.visibilityState === "visible") void load({ silent: true });
    };
    const interval = window.setInterval(refreshWhenActive, 3000);
    window.addEventListener("focus", refreshWhenActive);
    document.addEventListener("visibilitychange", refreshWhenActive);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener("focus", refreshWhenActive);
      document.removeEventListener("visibilitychange", refreshWhenActive);
    };
  }, [load]);
  useEffect(() => {
    void fetch("/api/auth/me", { cache: "no-store" }).then((response) => response.json()).then((payload: { user?: AppUser }) => setCurrentUser(payload.user || null)).catch(() => setCurrentUser(null));
  }, []);

  const visible = useMemo(() => {
    const term = normalize(query);
    return data.tools.filter((tool) => {
      if (!term && status && tool.estado !== status) return false;
      if (!term) return true;
      return normalize([tool.codigo, tool.nombre, tool.categoria, tool.marca, tool.descripcion, tool.espacio_ocupado, tool.empleado_actual, tool.vehiculo_actual, tool.estanteria?.codigo, tool.estanteria?.zona, tool.posicion].filter(Boolean).join(" ")).includes(term);
    });
  }, [data.tools, query, status]);

  async function action(tool: HerramientaComun, body: Record<string, unknown>, message: string) {
    setBusyId(tool.id); setError(""); setSuccess("");
    try {
      const response = await fetch(`/api/herramientas-comunes/${tool.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const payload = await response.json() as { error?: string };
      if (!response.ok) throw new Error(payload.error || "No se pudo actualizar la herramienta.");
      await load();
      setSuccess(message);
      setLoanTool(null);
      setLocationTool(null);
    } catch (caught) { setError(caught instanceof Error ? caught.message : "No se pudo actualizar la herramienta."); }
    finally { setBusyId(null); }
  }

  function handleScan(rawValue: string) {
    const parsed = parseCommonToolsQr(rawValue, window.location.origin);
    const mode = scannerMode;
    setScannerMode(null);
    setError(""); setSuccess("");
    if (parsed.kind === "tool" || parsed.kind === "tool-token") {
      if (mode === "return-location" || mode === "assign-location") {
        setError("Escanea la etiqueta del hueco de la estantería, no otra herramienta.");
        return;
      }
      const tool = parsed.kind === "tool-token" ? data.tools.find((item) => item.qr_token === parsed.token) : data.tools.find((item) => normalize(item.codigo) === normalize(parsed.code));
      if (!tool) { setError(parsed.kind === "tool-token" ? "Esta etiqueta QR no corresponde a ninguna herramienta activa." : `No encontramos la herramienta ${parsed.code}.`); return; }
      setScannedTool(tool);
      setQuery(tool.codigo);
      setMobileTab("buscar");
      return;
    }
    if (parsed.kind === "location") {
      const shelf = data.shelves.find((item) => item.id === parsed.shelfId);
      const row = shelf?.configuracion.filas.find((item) => item.nivel === parsed.level);
      if (!shelf || !row || Number(parsed.position.slice(1)) > row.columnas) { setError("Esta etiqueta pertenece a una ubicación que ya no existe en el plano."); return; }
      const locationValue = { shelf, level: parsed.level, position: parsed.position };
      if (mode === "assign-location" && placingTool) {
        const tool = placingTool;
        setPlacingTool(null);
        void action(tool, { action: "ubicacion", estanteria_id: shelf.id, nivel: parsed.level, posicion: parsed.position }, `${tool.nombre} colocada en ${locationName(shelf, parsed.level, parsed.position)}.`);
        return;
      }
      if (mode === "return-location" && returningTool) {
        const correct = returningTool.estanteria_id === shelf.id && returningTool.nivel === parsed.level && normalizePosition(returningTool.posicion) === parsed.position;
        if (correct) {
          const tool = returningTool;
          setReturningTool(null);
          void action(tool, { action: "devolver", estanteria_id: shelf.id, nivel: parsed.level, posicion: parsed.position }, `${tool.nombre} colocada por ${currentUser?.nombre || "el usuario actual"}.`);
        } else {
          setScannedLocation(locationValue);
        }
        return;
      }
      setScannedLocation(locationValue);
      setMobileTab("plano");
      return;
    }
    setError("No reconocemos este código QR.");
  }

  useEffect(() => {
    if (handledInitialQr.current || loading || !data.shelves.length) return;
    const params = new URLSearchParams(window.location.search);
    if (!params.has("herramienta") && !params.has("herramienta_qr") && !params.has("ubicacion")) return;
    handledInitialQr.current = true;
    const scannedUrl = window.location.href;
    window.history.replaceState({}, "", window.location.pathname);
    const timer = window.setTimeout(() => handleScan(scannedUrl), 0);
    return () => window.clearTimeout(timer);
    // Solo procesamos una vez el QR con el que se abrió la página.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, data.tools.length, data.shelves.length]);

  const available = data.tools.filter((tool) => tool.estado === "disponible").length;
  const loaned = data.tools.filter((tool) => tool.estado === "prestada").length;
  const missing = data.tools.filter((tool) => tool.estado === "perdida").length;
  const unlocatedTools = data.tools.filter((tool) => !tool.estanteria_id || tool.nivel === null || !tool.posicion);
  const mobileAttention = data.tools.filter((tool) => tool.estado === "perdida" || !tool.estanteria_id || tool.nivel === null || !tool.posicion).length;
  const isAdmin = currentUser?.rol === "administrador";
  const searching = Boolean(query.trim());
  function showLocation(tool: HerramientaComun) { setStatus(""); setQuery(tool.codigo); setMobileTab("buscar"); window.setTimeout(() => searchInput.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 0); }
  function showMissingTools() { setQuery(""); setStatus("perdida"); setView("lista"); setMobileTab("lista"); }
  function beginReturn(tool: HerramientaComun) {
    if (!data.settings.requireLocationScanOnReturn) {
      void action(tool, { action: "devolver" }, `${tool.nombre} colocada por ${currentUser?.nombre || "el usuario actual"}.`);
      return;
    }
    setReturningTool(tool); setScannerMode("return-location");
  }
  return <main onClick={(event) => { const target = event.target; if (target instanceof HTMLImageElement && target.currentSrc) setPhotoPreview({ url: target.currentSrc, alt: target.alt || "Fotografía de la herramienta" }); }} className="min-h-screen bg-gradient-to-br from-zinc-950 via-zinc-900 to-zinc-950 text-zinc-100">
    <header className="border-b border-zinc-800 bg-zinc-950/90"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-3 px-4 py-4 sm:px-6"><div className="flex min-w-0 items-center gap-3"><span className="rounded-xl border border-cyan-500/30 bg-cyan-500/10 p-2.5 text-cyan-300"><Wrench size={24} /></span><div><h1 className="truncate text-lg font-black">HERRAMIENTAS COMUNES</h1><p className="truncate text-xs text-zinc-500">Ubicación, disponibilidad y préstamos</p></div></div><Link href="/" className="inline-flex items-center gap-2 rounded-xl border border-zinc-700 px-3 py-2 text-sm font-bold text-zinc-300 hover:bg-zinc-800"><ArrowLeft size={16} /><span className="hidden sm:inline">Volver al inicio</span></Link></div></header>
    <div className="mx-auto max-w-[1500px] space-y-5 px-4 py-4 pb-28 sm:px-6 sm:py-6 sm:pb-6">
      <section className="hidden grid-cols-3 gap-3 sm:grid"><Summary label="Herramientas" value={data.tools.length} tone="cyan" /><Summary label="Disponibles" value={available} tone="emerald" /><Summary label="Prestadas" value={loaned} tone="amber" /></section>
      {error && <Notice tone="red">{error}</Notice>}{success && <Notice tone="green">{success}</Notice>}
      {setupRequired && <section className="rounded-2xl border border-amber-500/30 bg-amber-500/10 p-5"><h2 className="font-black text-amber-200">Falta activar la última actualización</h2><p className="mt-2 text-sm leading-6 text-amber-100/75">Aplica en la base de datos la actualización <strong>202608190002_layout_estanterias_herramientas.sql</strong> para cargar el plano configurable de las seis estanterías.</p></section>}
      <section className={`${mobileTab === "buscar" ? "block" : "hidden"} rounded-2xl border border-cyan-500/20 bg-zinc-900/95 p-3 shadow-2xl sm:block sm:p-4`}><div className="grid gap-2 sm:grid-cols-[1fr_auto]"><label className="relative block"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-cyan-400" size={21} /><input ref={searchInput} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="¿Qué herramienta buscas?" autoComplete="off" className="w-full rounded-xl border border-zinc-700 bg-zinc-950 py-4 pl-11 pr-11 text-base font-semibold outline-none focus:border-cyan-400 sm:py-3" />{searching && <button onClick={() => setQuery("")} aria-label="Limpiar búsqueda" className="absolute right-2 top-1/2 -translate-y-1/2 rounded-lg p-2 text-zinc-400 hover:bg-zinc-800"><X size={18} /></button>}</label><button onClick={() => { setReturningTool(null); setScannerMode("general"); }} className="inline-flex min-h-14 items-center justify-center gap-2 rounded-xl bg-cyan-400 px-5 font-black text-zinc-950 sm:min-h-0"><ScanLine size={21} /> Escanear QR</button></div>{searching && <p className="mt-2 px-1 text-xs font-bold text-cyan-300">{visible.length ? `${visible.length} resultado${visible.length === 1 ? "" : "s"} · ubicación mostrada en el plano` : "Sin resultados"}</p>}<div className="mt-3 hidden flex-wrap gap-2 sm:flex"><div className="grid grid-cols-3 rounded-xl border border-zinc-700 bg-zinc-950 p-1"><ViewButton active={view === "lista"} onClick={() => setView("lista")}><List size={17} /> Lista</ViewButton><ViewButton active={view === "prestamos"} onClick={() => setView("prestamos")}><UserRound size={17} /> Prestadas</ViewButton><ViewButton active={view === "estanterias"} onClick={() => setView("estanterias")}><LayoutGrid size={17} /> Plano</ViewButton></div><select value={status} onChange={(event) => setStatus(event.target.value as EstadoHerramienta | "")} className="min-w-0 rounded-xl border border-zinc-700 bg-zinc-950 px-3 py-3 text-sm outline-none focus:border-cyan-500"><option value="">Todos los estados</option>{Object.entries(STATUS).filter(([value]) => value !== "reparacion").map(([value, item]) => <option key={value} value={value}>{item.label}</option>)}</select>{isAdmin && <><button onClick={() => setCreating(true)} className="inline-flex items-center justify-center gap-2 rounded-xl bg-cyan-400 px-3 py-3 text-sm font-black text-zinc-950"><PackagePlus size={17} /> Registrar</button><button onClick={() => setManagingShelves(true)} className="inline-flex items-center justify-center gap-2 rounded-xl border border-zinc-700 px-3 py-3 text-sm font-bold text-zinc-300"><Settings size={17} /> Configurar estanterías</button><button onClick={() => setLabelsOpen(true)} className="inline-flex items-center justify-center gap-2 rounded-xl border border-amber-500/30 px-3 py-3 text-sm font-bold text-amber-200"><QrCode size={17} /> Etiquetas QR</button></>}</div></section>
      <div className="sm:hidden">{loading ? <Loading /> : mobileTab === "buscar" ? searching ? visible.length ? <SearchLocationResults tools={visible} shelves={data.shelves} onTool={setScannedTool} /> : <Empty text="No encontramos ninguna herramienta con ese nombre, código o marca." /> : <SearchPrompt /> : mobileTab === "lista" ? <ToolList tools={visible} admin={isAdmin} busyId={busyId} onLoan={setLoanTool} onReturn={beginReturn} onStatus={(tool, next) => void action(tool, { action: "estado", estado: next }, `${tool.nombre} actualizada.`)} onHistory={setHistoryTool} onLocation={setLocationTool} onEdit={setEditingTool} onShowLocation={showLocation} /> : mobileTab === "prestamos" ? <BorrowedToolsList tools={data.tools.filter((tool) => tool.estado === "prestada")} busyId={busyId} onReturn={beginReturn} onShowLocation={showLocation} /> : mobileTab === "plano" ? <ShelfView shelves={data.shelves} tools={data.tools} onTool={setScannedTool} /> : <MobileMore admin={isAdmin} status={status} missing={missing} unlocated={unlocatedTools.length} onStatus={setStatus} onMissing={showMissingTools} onUnlocated={() => setUnlocatedOpen(true)} onCreate={() => setCreating(true)} onShelves={() => setManagingShelves(true)} onLabels={() => setLabelsOpen(true)} />}</div>
      <div className="hidden sm:block">{loading ? <Loading /> : searching ? visible.length ? <SearchLocationResults tools={visible} shelves={data.shelves} onTool={setScannedTool} /> : <Empty text="No encontramos ninguna herramienta con ese nombre, código o marca." /> : view === "lista" ? <ToolList tools={visible} admin={isAdmin} busyId={busyId} onLoan={setLoanTool} onReturn={beginReturn} onStatus={(tool, next) => void action(tool, { action: "estado", estado: next }, `${tool.nombre} actualizada.`)} onHistory={setHistoryTool} onLocation={setLocationTool} onEdit={setEditingTool} onShowLocation={showLocation} /> : view === "prestamos" ? <BorrowedToolsList tools={data.tools.filter((tool) => tool.estado === "prestada")} busyId={busyId} onReturn={beginReturn} onShowLocation={showLocation} /> : <ShelfView shelves={data.shelves} tools={visible} onTool={setScannedTool} />}</div>
    </div>
    <MobileBottomNav active={mobileTab} loaned={loaned} missing={mobileAttention} onChange={(tab) => { setMobileTab(tab); if (tab !== "buscar") setQuery(""); else window.setTimeout(() => searchInput.current?.focus(), 0); }} />
    {creating && <CreateToolModal shelves={data.shelves} requirePhoto={data.settings.requirePhotoOnCreate} onClose={() => setCreating(false)} onCreated={async (toolId, located) => { setCreating(false); const refreshed = await load(); setLabelTool(refreshed?.tools.find((tool) => tool.id === toolId) || null); setSuccess(located ? "Herramienta registrada en su ubicación." : "Herramienta registrada sin ubicación. Puedes colocarla después mediante QR o desde el plano."); }} />}
    {managingShelves && <ShelfManager shelves={data.shelves} onClose={() => setManagingShelves(false)} onChanged={() => void load()} />}
    {loanTool && <LoanModal tool={loanTool} currentUser={currentUser} actionUsers={actionUsers} actionUsersLoading={actionUsersLoading} askVehicle={data.settings.askVehicleOnLoan} requireVehicle={data.settings.requireVehicleOnLoan} busy={busyId === loanTool.id} onClose={() => setLoanTool(null)} onConfirm={(vehicle, actorUserId, actorName) => void action(loanTool, { action: "retirar", vehiculo: vehicle, actor_user_id: actorUserId }, `${loanTool.nombre} retirada por ${actorName || currentUser?.nombre || "el usuario actual"}.`)} />}
    {historyTool && <HistoryModal tool={historyTool} movements={data.movements.filter((item) => item.herramienta_id === historyTool.id)} onClose={() => setHistoryTool(null)} />}
    {locationTool && <LocationModal tool={locationTool} shelves={data.shelves} busy={busyId === locationTool.id} onClose={() => setLocationTool(null)} onConfirm={(shelfId, level, position) => void action(locationTool, { action: "ubicacion", estanteria_id: shelfId, nivel: level, posicion: position }, `${locationTool.nombre} movida a su nueva ubicación.`)} />}
    {editingTool && <EditToolModal tool={editingTool} onClose={() => setEditingTool(null)} onSaved={async () => { const toolId = editingTool.id; setEditingTool(null); const refreshed = await load(); setLabelTool(refreshed?.tools.find((tool) => tool.id === toolId) || null); setSuccess("Herramienta actualizada correctamente."); }} />}
    {scannerMode && <BarcodeScanner allowManualEntry={scannerMode === "general" || data.settings.allowManualLocationCode} title={scannerMode === "return-location" ? "Escanear lugar de devolución" : scannerMode === "assign-location" ? "Escanear dónde la colocas" : "Escanear herramienta o ubicación"} description={scannerMode === "return-location" ? `Busca la etiqueta de ${location(returningTool!)}` : scannerMode === "assign-location" ? `Escanea el QR del hueco donde guardas ${placingTool?.nombre || "la herramienta"}.` : "Apunta al QR de una herramienta o de un hueco."} manualPlaceholder={scannerMode === "general" ? "Código de herramienta o ubicación" : "Ej. UB-5-N3-C2"} manualHint={scannerMode === "general" ? "También puedes escribir el código visible de la herramienta o ubicación." : "Si la cámara falla, escribe el código UB impreso junto al QR de la ubicación."} onScan={handleScan} onClose={() => { setScannerMode(null); if (scannerMode === "return-location") setReturningTool(null); if (scannerMode === "assign-location") setPlacingTool(null); }} />}
    {scannedTool && <ScannedToolModal tool={scannedTool} busy={busyId === scannedTool.id} onClose={() => setScannedTool(null)} onLoan={() => { const tool = scannedTool; setScannedTool(null); setLoanTool(tool); }} onReturn={() => { const tool = scannedTool; setScannedTool(null); beginReturn(tool); }} onPlace={() => { const tool = scannedTool; setScannedTool(null); setPlacingTool(tool); setScannerMode("assign-location"); }} onChoosePlan={() => { const tool = scannedTool; setScannedTool(null); setPlanTool(tool); }} onShowLocation={() => { const tool = scannedTool; setScannedTool(null); showLocation(tool); }} />}
    {planTool && <PlaceToolPlanModal tool={planTool} shelves={data.shelves} busy={busyId === planTool.id} onClose={() => setPlanTool(null)} onConfirm={(shelf, level, position) => { const tool = planTool; setPlanTool(null); void action(tool, { action: "ubicacion", estanteria_id: shelf.id, nivel: level, posicion: position }, `${tool.nombre} colocada en ${locationName(shelf, level, position)}.`); }} />}
    {unlocatedOpen && <UnlocatedToolsModal tools={unlocatedTools} onClose={() => setUnlocatedOpen(false)} onScan={(tool) => { setUnlocatedOpen(false); setPlacingTool(tool); setScannerMode("assign-location"); }} onPlan={(tool) => { setUnlocatedOpen(false); setPlanTool(tool); }} />}
    {scannedLocation && <ScannedLocationModal value={scannedLocation} tools={data.tools.filter((tool) => tool.estanteria_id === scannedLocation.shelf.id && tool.nivel === scannedLocation.level && normalizePosition(tool.posicion) === scannedLocation.position)} returningTool={returningTool} onClose={() => { setScannedLocation(null); setReturningTool(null); }} onRetry={() => { setScannedLocation(null); setScannerMode("return-location"); }} />}
    {labelsOpen && <LabelsModal tools={data.tools} shelves={data.shelves} onClose={() => setLabelsOpen(false)} />}
    {labelTool && <ToolLabelAfterSaveModal tool={labelTool} onClose={() => setLabelTool(null)} />}
    {photoPreview && <PhotoPreview url={photoPreview.url} alt={photoPreview.alt} onClose={() => setPhotoPreview(null)} />}
  </main>;
}

type ToolListProps = { tools: HerramientaComun[]; admin: boolean; busyId: number | null; onLoan: (tool: HerramientaComun) => void; onReturn: (tool: HerramientaComun) => void; onStatus: (tool: HerramientaComun, status: EstadoHerramienta) => void; onHistory: (tool: HerramientaComun) => void; onLocation: (tool: HerramientaComun) => void; onEdit: (tool: HerramientaComun) => void; onShowLocation: (tool: HerramientaComun) => void };

function ToolList(props: ToolListProps) {
  if (props.admin) return <AdminToolList {...props} />;
  if (!props.tools.length) return <Empty />;
  return <section className="grid gap-3 xl:grid-cols-2">{props.tools.map((tool) => <article key={tool.id} className="overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-900/85"><div className="flex gap-3 p-4">{tool.foto_url ? <img src={tool.foto_url} alt="" className="h-16 w-16 shrink-0 rounded-xl object-cover" /> : <span className="flex h-16 w-16 shrink-0 items-center justify-center rounded-xl bg-zinc-950 text-zinc-600"><Wrench /></span>}<div className="min-w-0 flex-1"><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><h2 className="truncate font-black text-white">{tool.nombre}</h2><span className="flex flex-wrap items-center gap-2"><StatusBadge status={tool.estado} /><ToolModeBadge tool={tool} /></span>{tool.estado === "prestada" && <p className="mt-2 text-sm font-bold text-amber-200">La tiene {tool.empleado_actual}</p>}</div></div><footer className="grid grid-cols-2 gap-2 border-t border-zinc-800 p-3"><button onClick={() => props.onShowLocation(tool)} className="col-span-2 flex min-h-14 items-center gap-3 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 text-left font-black text-amber-100"><MapPin className="shrink-0" /><span><span className="block">{location(tool)}</span>{tool.espacio_ocupado && <span className="block text-xs font-bold text-violet-200/80">Ocupa: {tool.espacio_ocupado}</span>}</span></button>{tool.estado === "disponible" && !tool.solo_localizacion && <button onClick={() => props.onLoan(tool)} className="col-span-2 min-h-12 rounded-xl bg-cyan-400 font-black text-zinc-950">Retirar herramienta</button>}{tool.estado === "prestada" && <button disabled={props.busyId === tool.id} onClick={() => props.onReturn(tool)} className="col-span-2 min-h-12 rounded-xl bg-emerald-400 font-black text-zinc-950 disabled:opacity-50">Devolver herramienta</button>}<button onClick={() => props.onHistory(tool)} className="action"><History size={15} /> Historial</button>{(tool.estado === "reparacion" || tool.estado === "perdida") ? <button onClick={() => props.onStatus(tool, "disponible")} className="action action-success"><CheckCircle2 size={15} /> Disponible</button> : tool.estado !== "prestada" ? <button onClick={() => props.onStatus(tool, "perdida")} className="action text-red-300"><AlertTriangle size={15} /> No localizada</button> : null}</footer></article>)}</section>;
}

function AdminToolList({ tools, admin, busyId, onLoan, onReturn, onStatus, onHistory, onLocation, onEdit, onShowLocation }: ToolListProps) {
  void admin;
  if (!tools.length) return <Empty />;
  return <section className="grid gap-3 xl:grid-cols-2">{tools.map((tool) => <article key={tool.id} className="overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-900/85"><div className="flex gap-3 p-4">{tool.foto_url ? <img src={tool.foto_url} alt="" className="h-16 w-16 shrink-0 rounded-xl border border-zinc-700 object-cover sm:h-20 sm:w-20" /> : <span className="flex h-16 w-16 shrink-0 items-center justify-center rounded-xl border border-zinc-700 bg-zinc-950 text-zinc-600 sm:h-20 sm:w-20"><Wrench size={28} /></span>}<div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><h2 className="truncate text-base font-black text-white sm:text-lg">{tool.nombre}</h2><p className="truncate text-xs text-zinc-500">{[tool.marca, tool.categoria].filter(Boolean).join(" · ") || "Sin categoría"}</p></div><span className="flex flex-wrap items-center gap-2"><StatusBadge status={tool.estado} /><ToolModeBadge tool={tool} /></span></div>{tool.estado === "prestada" && <p className="mt-2 text-sm font-bold text-amber-200">La tiene {tool.empleado_actual}{tool.vehiculo_actual ? ` · ${tool.vehiculo_actual}` : ""}</p>}</div></div><footer className="grid grid-cols-2 gap-2 border-t border-zinc-800 bg-zinc-950/35 p-3"><button onClick={() => onShowLocation(tool)} className="col-span-2 inline-flex min-h-14 items-center justify-start gap-3 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 text-left text-amber-100"><MapPin className="shrink-0 text-amber-300" size={20} /><span className="min-w-0"><span className="block font-black">{location(tool)}</span>{tool.espacio_ocupado && <span className="block text-[11px] font-bold text-violet-200/80">Ocupa: {tool.espacio_ocupado}</span>}<span className="block text-[11px] text-amber-200/60">Pulsa para verlo en el plano</span></span></button>{tool.estado === "disponible" && !tool.solo_localizacion && <button onClick={() => onLoan(tool)} className="col-span-2 inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-cyan-400 font-black text-zinc-950"><Wrench size={18} /> Retirar herramienta</button>}{tool.estado === "prestada" && <button disabled={busyId === tool.id} onClick={() => onReturn(tool)} className="col-span-2 inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-emerald-400 font-black text-zinc-950 disabled:opacity-50">{busyId === tool.id ? <Loader2 className="animate-spin" size={18} /> : <RotateCcw size={18} />} Devolver herramienta</button>}<details className="col-span-2"><summary className="cursor-pointer py-2 text-center text-xs font-bold text-zinc-500">Más acciones</summary><div className="mt-1 flex flex-wrap justify-center gap-2"><button onClick={() => onEdit(tool)} className="action action-primary"><Edit3 size={15} /> Editar</button><button onClick={() => onHistory(tool)} className="action"><History size={15} /> Historial</button><button onClick={() => onLocation(tool)} className="action"><MapPin size={15} /> Mover</button>{(tool.estado === "reparacion" || tool.estado === "perdida") && <button onClick={() => onStatus(tool, "disponible")} className="action action-success"><CheckCircle2 size={15} /> Disponible</button>}{tool.estado !== "perdida" && tool.estado !== "prestada" && <button onClick={() => onStatus(tool, "perdida")} className="action text-red-300"><AlertTriangle size={15} /> No localizada</button>}</div></details></footer></article>)}</section>;
}

function BorrowedToolsList({ tools, busyId, onReturn, onShowLocation }: { tools: HerramientaComun[]; busyId: number | null; onReturn: (tool: HerramientaComun) => void; onShowLocation: (tool: HerramientaComun) => void }) {
  if (!tools.length) return <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/10 px-5 py-12 text-center"><CheckCircle2 className="mx-auto mb-3 text-emerald-300" size={42} /><h2 className="font-black text-emerald-100">Todas están devueltas</h2><p className="mt-1 text-sm text-emerald-200/60">Ahora mismo nadie tiene herramientas prestadas.</p></div>;
  const groups = Object.entries(Object.groupBy(tools, (tool) => tool.empleado_actual || "Sin empleado")).sort(([left], [right]) => left.localeCompare(right, "es"));
  return <div className="space-y-5"><header><h2 className="text-xl font-black text-white">Quién tiene cada herramienta</h2><p className="text-sm text-zinc-500">{tools.length} herramienta{tools.length === 1 ? "" : "s"} fuera de su ubicación</p></header>{groups.map(([employee, employeeTools]) => <section key={employee} className="overflow-hidden rounded-2xl border border-amber-500/25 bg-zinc-900/85"><header className="flex items-center justify-between bg-amber-500/10 px-4 py-3"><span className="flex items-center gap-2 font-black text-amber-100"><UserRound size={19} />{employee}</span><span className="rounded-full bg-amber-400 px-2.5 py-1 text-xs font-black text-zinc-950">{employeeTools?.length || 0}</span></header><div className="divide-y divide-zinc-800">{employeeTools?.map((tool) => <article key={tool.id} className="p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><h3 className="font-black text-white">{tool.nombre}</h3>{tool.vehiculo_actual && <p className="mt-1 text-sm font-bold text-amber-200">Vehículo: {tool.vehiculo_actual}</p>}<p className="mt-1 flex items-center gap-1 text-xs text-zinc-500"><Clock3 size={13} />Desde {formatDate(tool.retirada_at)}</p></div>{tool.foto_url && <img src={tool.foto_url} alt="" className="h-14 w-14 rounded-lg object-cover" />}</div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={() => onShowLocation(tool)} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-amber-500/30 text-sm font-bold text-amber-200"><MapPin size={16} /> Sitio de devolución</button><button disabled={busyId === tool.id} onClick={() => onReturn(tool)} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-emerald-400 text-sm font-black text-zinc-950 disabled:opacity-50">{busyId === tool.id ? <Loader2 className="animate-spin" size={16} /> : <RotateCcw size={16} />} Devolver</button></div></article>)}</div></section>)}</div>;
}

function MobileMore({ admin, status, missing, unlocated, onStatus, onMissing, onUnlocated, onCreate, onShelves, onLabels }: { admin: boolean; status: EstadoHerramienta | ""; missing: number; unlocated: number; onStatus: (status: EstadoHerramienta | "") => void; onMissing: () => void; onUnlocated: () => void; onCreate: () => void; onShelves: () => void; onLabels: () => void }) {
  if (!admin) return <div className="space-y-4"><div><h2 className="text-xl font-black">Más opciones</h2><p className="text-sm text-zinc-500">Listas y filtros</p></div><UnlocatedMoreButton count={unlocated} onClick={onUnlocated} /><button onClick={onMissing} className={`flex min-h-16 w-full items-center justify-between gap-3 rounded-2xl border px-4 text-left ${missing ? "border-red-500/35 bg-red-500/10 text-red-100" : "border-emerald-500/25 bg-emerald-500/10 text-emerald-100"}`}><span className="flex items-center gap-3"><AlertTriangle size={23} /><span><span className="block font-black">Herramientas no localizadas</span><span className="block text-xs opacity-60">Ver la lista completa</span></span></span><span className="flex h-9 min-w-9 items-center justify-center rounded-full bg-red-400 px-2 font-black text-zinc-950">{missing}</span></button><Field label="Filtrar la lista"><select value={status} onChange={(event) => onStatus(event.target.value as EstadoHerramienta | "")} className="input"><option value="">Todas las herramientas</option><option value="disponible">Disponibles</option><option value="prestada">Prestadas</option><option value="perdida">No localizadas</option></select></Field></div>;
  return <div className="space-y-4"><div><h2 className="text-xl font-black">Más opciones</h2><p className="text-sm text-zinc-500">Administración y filtros</p></div><UnlocatedMoreButton count={unlocated} onClick={onUnlocated} /><button onClick={onMissing} className={`flex min-h-16 w-full items-center justify-between gap-3 rounded-2xl border px-4 text-left ${missing ? "border-red-500/35 bg-red-500/10 text-red-100" : "border-emerald-500/25 bg-emerald-500/10 text-emerald-100"}`}><span className="flex items-center gap-3"><AlertTriangle size={23} className={missing ? "text-red-300" : "text-emerald-300"} /><span><span className="block font-black">Herramientas no localizadas</span><span className="block text-xs opacity-60">Ver la lista completa</span></span></span><span className={`flex h-9 min-w-9 items-center justify-center rounded-full px-2 font-black ${missing ? "bg-red-400 text-zinc-950" : "bg-emerald-400 text-zinc-950"}`}>{missing}</span></button><button onClick={onCreate} className="flex min-h-14 w-full items-center justify-center gap-3 rounded-2xl bg-cyan-400 font-black text-zinc-950"><PackagePlus size={21} /> Registrar herramienta</button><button onClick={onLabels} className="flex min-h-14 w-full items-center justify-center gap-3 rounded-2xl border border-amber-500/30 bg-amber-500/10 font-black text-amber-200"><QrCode size={21} /> Imprimir etiquetas QR</button><button onClick={onShelves} className="flex min-h-14 w-full items-center justify-center gap-3 rounded-2xl border border-zinc-700 bg-zinc-900 font-bold text-zinc-200"><Settings size={21} /> Configurar estanterías</button><Field label="Filtrar la lista"><select value={status} onChange={(event) => onStatus(event.target.value as EstadoHerramienta | "")} className="input"><option value="">Todas las herramientas</option><option value="disponible">Disponibles</option><option value="prestada">Prestadas</option><option value="perdida">No localizadas</option></select></Field></div>;
}

function UnlocatedMoreButton({ count, onClick }: { count: number; onClick: () => void }) {
  return <button onClick={onClick} className={`flex min-h-16 w-full items-center justify-between gap-3 rounded-2xl border px-4 text-left ${count ? "border-cyan-500/35 bg-cyan-500/10 text-cyan-100" : "border-emerald-500/25 bg-emerald-500/10 text-emerald-100"}`}><span className="flex items-center gap-3"><MapPin size={23} className={count ? "text-cyan-300" : "text-emerald-300"} /><span><span className="block font-black">Sin ubicación</span><span className="block text-xs opacity-60">Colocarlas rápidamente</span></span></span><span className={`flex h-9 min-w-9 items-center justify-center rounded-full px-2 font-black text-zinc-950 ${count ? "bg-cyan-300" : "bg-emerald-400"}`}>{count}</span></button>;
}

type MobileTab = "buscar" | "lista" | "prestamos" | "plano" | "mas";
function MobileBottomNav({ active, loaned, missing, onChange }: { active: MobileTab; loaned: number; missing: number; onChange: (tab: MobileTab) => void }) {
  return <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-zinc-700 bg-zinc-950/95 px-1 pb-[env(safe-area-inset-bottom)] shadow-[0_-8px_30px_rgba(0,0,0,0.45)] backdrop-blur sm:hidden"><div className="mx-auto grid max-w-lg grid-cols-5"><BottomNavButton active={active === "lista"} label="Lista" icon={<List />} onClick={() => onChange("lista")} /><BottomNavButton active={active === "prestamos"} label="Prestadas" icon={<UserRound />} badge={loaned} onClick={() => onChange("prestamos")} /><BottomNavButton prominent active={active === "buscar"} label="Buscar" icon={<Search />} onClick={() => onChange("buscar")} /><BottomNavButton active={active === "plano"} label="Plano" icon={<LayoutGrid />} onClick={() => onChange("plano")} /><BottomNavButton active={active === "mas"} label="Más" icon={<MoreHorizontal />} badge={missing} badgeTone="red" onClick={() => onChange("mas")} /></div></nav>;
}
function BottomNavButton({ active, label, icon, badge, badgeTone = "amber", onClick, prominent = false }: { active: boolean; label: string; icon: ReactNode; badge?: number; badgeTone?: "amber" | "red"; onClick: () => void; prominent?: boolean }) { if (prominent) return <button onClick={onClick} className="relative flex min-h-16 flex-col items-center justify-end gap-0.5 pb-1 text-[11px] font-black text-cyan-200"><span className={`absolute -top-7 flex h-16 w-16 items-center justify-center rounded-full border-4 border-zinc-950 shadow-[0_5px_20px_rgba(34,211,238,0.35)] [&>svg]:h-7 [&>svg]:w-7 ${active ? "bg-cyan-300 text-zinc-950 ring-4 ring-cyan-400/20" : "bg-cyan-500 text-zinc-950"}`}>{icon}</span>{label}</button>; return <button onClick={onClick} className={`relative flex min-h-16 flex-col items-center justify-center gap-1 rounded-xl text-[10px] font-black ${active ? "text-cyan-300" : "text-zinc-500"}`}><span className={`[&>svg]:h-5 [&>svg]:w-5 ${active ? "rounded-xl bg-cyan-500/15 p-1 [&>svg]:h-6 [&>svg]:w-6" : ""}`}>{icon}</span>{label}{Boolean(badge) && <span className={`absolute right-2 top-1.5 flex h-5 min-w-5 items-center justify-center rounded-full px-1 text-[10px] text-zinc-950 ${badgeTone === "red" ? "bg-red-400" : "bg-amber-400"}`}>{badge}</span>}</button>; }
function Loading() { return <div className="flex justify-center py-20"><Loader2 className="animate-spin text-cyan-300" size={36} /></div>; }
function SearchPrompt() { return <div className="rounded-2xl border border-dashed border-cyan-500/20 bg-cyan-500/5 px-5 py-16 text-center"><Search className="mx-auto mb-4 text-cyan-500/50" size={48} /><h2 className="font-black text-white">Busca una herramienta</h2><p className="mx-auto mt-2 max-w-xs text-sm leading-6 text-zinc-500">Escribe su nombre, código o marca y te mostraremos exactamente dónde está.</p></div>; }

function SearchLocationResults({ tools, shelves, onTool }: { tools: HerramientaComun[]; shelves: EstanteriaHerramientas[]; onTool: (tool: HerramientaComun) => void }) {
  return <div className="space-y-4"><section className="grid gap-2 sm:grid-cols-2">{tools.map((tool) => <button type="button" key={tool.id} onClick={() => onTool(tool)} className={`rounded-xl border p-4 text-left transition active:scale-[0.99] ${tool.estado === "prestada" ? "border-amber-500/30 bg-amber-500/10" : "border-cyan-500/30 bg-cyan-500/10"}`}><div className="flex items-start justify-between gap-2"><div><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><h2 className="font-black text-white">{tool.nombre}</h2></div><span className="flex flex-wrap justify-end gap-2"><StatusBadge status={tool.estado} /><ToolModeBadge tool={tool} /></span></div>{tool.estado === "prestada" ? <p className="mt-3 text-sm font-bold text-amber-100"><UserRound className="mr-1 inline" size={16} /> La tiene {tool.empleado_actual}{tool.vehiculo_actual ? ` · ${tool.vehiculo_actual}` : ""}</p> : <p className="mt-3 flex items-start gap-2 text-sm font-black text-cyan-100"><MapPin className="mt-0.5 shrink-0" size={17} />{location(tool)}</p>}{tool.espacio_ocupado && <p className="mt-2 text-sm font-bold text-violet-200">Ocupa: {tool.espacio_ocupado}</p>}<span className="mt-3 block text-xs font-black text-white/70">Pulsa para abrir y actuar</span></button>)}</section><ShelfView shelves={shelves} tools={tools} onTool={onTool} highlight /></div>;
}

function ShelfView({ shelves, tools, onTool, highlight = false }: { shelves: EstanteriaHerramientas[]; tools: HerramientaComun[]; onTool: (tool: HerramientaComun) => void; highlight?: boolean }) {
  const visibleShelves = highlight ? shelves.filter((shelf) => tools.some((tool) => tool.estanteria_id === shelf.id)) : shelves;
  const zones = Object.entries(Object.groupBy(visibleShelves, (shelf) => shelf.zona));
  return <div className="space-y-8">{zones.map(([zone, zoneShelves]) => <section key={zone}><div className="mb-4 flex items-center gap-3"><span className="rounded-xl bg-cyan-500/10 p-2 text-cyan-300"><MapPin size={20} /></span><div><h2 className="text-xl font-black">{zone}</h2><p className="text-xs text-zinc-500">{highlight ? "Ubicación encontrada · pulsa la herramienta para abrirla" : `${zoneShelves?.length || 0} estanterías · pulsa una herramienta para abrirla`}</p></div></div><div className="grid items-start gap-5 md:grid-cols-2 2xl:grid-cols-4">{zoneShelves?.map((shelf) => <VisualShelf key={shelf.id} shelf={shelf} tools={tools.filter((tool) => tool.estanteria_id === shelf.id)} onTool={onTool} highlight={highlight} />)}</div></section>)}</div>;
}

function VisualShelf({ shelf, tools, onTool, highlight = false }: { shelf: EstanteriaHerramientas; tools: HerramientaComun[]; onTool: (tool: HerramientaComun) => void; highlight?: boolean }) {
  const rows = shelf.configuracion?.filas?.length ? shelf.configuracion.filas : fallbackRows(shelf.niveles);
  return <article className={`overflow-hidden rounded-2xl border bg-zinc-900 shadow-xl ${highlight ? "border-cyan-300 ring-4 ring-cyan-400/20" : "border-zinc-700"}`}><header className="flex items-start justify-between border-b border-zinc-700 bg-zinc-950/70 p-4"><div><p className="font-mono text-xs font-black text-cyan-300">{shelf.codigo}</p><h3 className="font-black text-white">{shelf.nombre}</h3></div><span className="rounded-full bg-zinc-800 px-2.5 py-1 text-[10px] font-bold text-zinc-400">{tools.length} herramientas</span></header><div className="border-x-4 border-b-4 border-zinc-600 bg-zinc-950 p-1">{rows.map((row) => <div key={row.nivel} className={`relative grid border-b-4 border-zinc-600 last:border-b-0 ${row.tipo === "colgador" ? "bg-amber-950/15" : "bg-zinc-900/60"}`} style={{ gridTemplateColumns: `repeat(${row.columnas}, minmax(0, 1fr))`, minHeight: `${Math.max(68, row.altura * 62)}px` }}>{Array.from({ length: row.columnas }, (_, index) => `C${index + 1}`).map((position) => { const cellTools = tools.filter((tool) => tool.nivel === row.nivel && normalizePosition(tool.posicion) === position); return <div key={position} className={`relative flex min-w-0 flex-col gap-1 border-r-2 p-1.5 last:border-r-0 ${highlight && cellTools.length ? "border-cyan-300 bg-cyan-400/10 ring-2 ring-inset ring-cyan-300" : "border-zinc-700"}`}><div className={`flex items-center justify-between gap-1 text-[9px] font-bold uppercase ${highlight && cellTools.length ? "text-cyan-200" : "text-zinc-600"}`}><span>{row.nombre}</span>{row.columnas > 1 && <span>{position}</span>}</div>{row.tipo === "colgador" && !cellTools.length && <div className="flex flex-1 items-center justify-center"><Grip className="text-amber-700/50" size={28} /><span className="sr-only">Zona para colgar</span></div>}{cellTools.map((tool) => <button key={tool.id} onClick={() => onTool(tool)} title={`${tool.nombre} · ${STATUS[tool.estado].label}`} className={`min-w-0 rounded-lg border px-2 py-2 text-left text-[11px] font-bold leading-tight ${STATUS[tool.estado].classes} ${highlight ? "animate-pulse ring-2 ring-white/70" : ""}`}><span className="block truncate">{tool.nombre}</span>{tool.solo_localizacion && <span className="block truncate text-[9px] font-black text-violet-200">Solo localizar</span>}{tool.espacio_ocupado && <span className="block truncate text-[9px] font-normal opacity-75">Ocupa: {tool.espacio_ocupado}</span>}{tool.estado === "prestada" && <span className="block truncate text-[9px] font-normal opacity-75">La tiene {tool.empleado_actual}</span>}</button>)}</div>; })}</div>)}</div><footer className="flex items-center justify-between bg-zinc-950/40 px-4 py-2 text-[10px] text-zinc-500"><span>{rows.length} niveles</span><span>{rows.reduce((sum, row) => sum + row.columnas, 0)} espacios</span></footer></article>;
}

function CreateToolModal({ shelves, requirePhoto, onClose, onCreated }: { shelves: EstanteriaHerramientas[]; requirePhoto: boolean; onClose: () => void; onCreated: (toolId: number, located: boolean) => void | Promise<void> }) {
  const [saving, setSaving] = useState(false); const [savingText, setSavingText] = useState(""); const [error, setError] = useState(""); const [photo, setPhoto] = useState<File | null>(null); const [preview, setPreview] = useState(""); const [createdId, setCreatedId] = useState<number | null>(null);
  const [assignLocation, setAssignLocation] = useState(false); const [shelfId, setShelfId] = useState(shelves[0]?.id || 0); const [level, setLevel] = useState(shelves[0]?.configuracion?.filas?.[0]?.nivel || 1); const [position, setPosition] = useState("C1");
  const selectedShelf = shelves.find((shelf) => shelf.id === shelfId) || shelves[0]; const selectedRows = selectedShelf?.configuracion?.filas || []; const selectedLevel = selectedRows.some((row) => row.nivel === level) ? level : selectedRows[0]?.nivel || 1; const selectedRow = selectedRows.find((row) => row.nivel === selectedLevel); const selectedPosition = Number(position.slice(1)) <= (selectedRow?.columnas || 1) ? position : "C1";
  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]);
  function selectPhoto(file?: File) { setError(""); if (!file) return; if (!file.type.startsWith("image/") || file.size > PHOTO_SOURCE_MAX_BYTES) { setError("Selecciona una fotografía válida de hasta 30 MB."); return; } setPhoto(file); setPreview(URL.createObjectURL(file)); }
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (requirePhoto && !photo) { setError("Haz una foto inicial antes de registrar la herramienta."); return; } setSaving(true); setError(""); const form = new FormData(event.currentTarget); const body = { ...Object.fromEntries(form.entries()), ...(assignLocation && selectedShelf ? { estanteria_id: selectedShelf.id, nivel: selectedLevel, posicion: selectedPosition } : {}) }; try { let toolId = createdId; if (!toolId) { setSavingText("Registrando herramienta..."); const response = await fetch("/api/herramientas-comunes", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const payload = await response.json() as HerramientaComun & { error?: string }; if (!response.ok) throw new Error(payload.error || "No se pudo registrar."); toolId = payload.id; setCreatedId(toolId); } if (photo) { setSavingText("Preparando fotografía..."); const optimized = await optimizePhoto(photo); setSavingText("Guardando fotografía inicial..."); const photoResponse = await fetch(`/api/herramientas-comunes/${toolId}/foto`, { method: "POST", headers: { "Content-Type": optimized.type || "application/octet-stream", "X-Photo-Name": encodeURIComponent(optimized.name) }, body: optimized }); const photoPayload = await photoResponse.json() as { error?: string }; if (!photoResponse.ok) throw new Error(`La herramienta está registrada, pero falta la foto: ${photoPayload.error || "no se pudo guardar"}. Pulsa de nuevo para reintentar.`); } await onCreated(toolId, assignLocation && Boolean(selectedShelf)); } catch (caught) { setError(caught instanceof Error ? caught.message : "No se pudo registrar."); } finally { setSaving(false); setSavingText(""); } }
  return <Modal title="Registrar herramienta común" subtitle="El código se genera solo y podrás colocarla después con los QR" onClose={onClose}><form onSubmit={submit} className="space-y-4">{error && <Notice tone="red">{error}</Notice>}<section className="space-y-3 rounded-2xl border border-zinc-700 bg-zinc-950/45 p-4"><div><p className="font-black text-white">Ubicación (opcional)</p><p className="mt-1 text-xs leading-5 text-zinc-500">Puedes colocarla ahora o dejarlo pendiente para usar después el QR o el plano.</p></div><div className="grid grid-cols-2 gap-2"><button type="button" disabled={Boolean(createdId)} onClick={() => setAssignLocation(false)} className={`min-h-12 rounded-xl border px-3 text-sm font-black ${!assignLocation ? "border-amber-400 bg-amber-400 text-zinc-950" : "border-zinc-700 text-zinc-400"}`}>Sin ubicación</button><button type="button" disabled={Boolean(createdId) || !shelves.length} onClick={() => setAssignLocation(true)} className={`min-h-12 rounded-xl border px-3 text-sm font-black disabled:opacity-40 ${assignLocation ? "border-cyan-400 bg-cyan-400 text-zinc-950" : "border-zinc-700 text-zinc-400"}`}>Asignar ahora</button></div>{assignLocation && selectedShelf && <div className="grid gap-3 rounded-xl border border-cyan-500/25 bg-cyan-500/5 p-3 sm:grid-cols-3"><Field label="Estantería"><select value={selectedShelf.id} onChange={(event) => { const nextId = Number(event.target.value); const nextShelf = shelves.find((shelf) => shelf.id === nextId); setShelfId(nextId); setLevel(nextShelf?.configuracion?.filas?.[0]?.nivel || 1); setPosition("C1"); }} className="input">{shelves.map((shelf) => <option key={shelf.id} value={shelf.id}>{shelf.zona} · {shelf.codigo}</option>)}</select></Field><Field label="Nivel"><select value={selectedLevel} onChange={(event) => { setLevel(Number(event.target.value)); setPosition("C1"); }} className="input">{selectedRows.map((row) => <option key={row.nivel} value={row.nivel}>{row.nombre}</option>)}</select></Field><Field label="Compartimento"><select value={selectedPosition} onChange={(event) => setPosition(event.target.value)} className="input">{Array.from({ length: selectedRow?.columnas || 1 }, (_, itemIndex) => <option key={itemIndex} value={`C${itemIndex + 1}`}>{selectedRow && selectedRow.columnas > 1 ? `Compartimento ${itemIndex + 1}` : "Espacio completo"}</option>)}</select></Field><p className="sm:col-span-3 text-sm font-bold text-cyan-100"><MapPin className="mr-1 inline" size={16} />{locationName(selectedShelf, selectedLevel, selectedPosition)}</p></div>}</section><div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre *"><input name="nombre" required disabled={Boolean(createdId)} className="input disabled:opacity-50" placeholder="Ej. Maletín de diagnosis" /></Field><Field label="Categoría"><input name="categoria" disabled={Boolean(createdId)} className="input disabled:opacity-50" placeholder="Diagnosis, elevación..." /></Field><Field label="Marca"><input name="marca" disabled={Boolean(createdId)} className="input disabled:opacity-50" /></Field><div className="sm:col-span-2"><span className="mb-2 block text-xs font-bold uppercase tracking-wide text-zinc-400">Foto inicial (opcional)</span><div className="grid gap-3 rounded-2xl border border-dashed border-cyan-500/30 bg-cyan-500/5 p-3 sm:grid-cols-[160px_1fr]">{preview ? <div className="relative overflow-hidden rounded-xl border border-cyan-400/40"><img src={preview} alt="Vista previa de la herramienta" className="aspect-square h-full w-full object-cover" /><button type="button" onClick={() => { setPhoto(null); setPreview(""); }} className="absolute right-2 top-2 rounded-lg bg-black/70 p-2 text-white" aria-label="Quitar foto"><X size={16} /></button></div> : <div className="flex aspect-video items-center justify-center rounded-xl bg-zinc-950 text-zinc-700 sm:aspect-square"><Camera size={40} /></div>}<div className="flex flex-col justify-center gap-2"><p className="text-sm font-bold text-cyan-100">Fotografía cómo está antes de empezar a usarla.</p><p className="text-xs leading-5 text-zinc-500">Servirá como referencia del estado y del contenido original.</p><div className="grid grid-cols-2 gap-2"><label className="inline-flex min-h-12 cursor-pointer items-center justify-center gap-2 rounded-xl bg-cyan-400 px-3 text-sm font-black text-zinc-950"><input type="file" accept="image/*" capture="environment" className="hidden" onChange={(event) => selectPhoto(event.target.files?.[0])} /><Camera size={18} /> Hacer foto</label><label className="inline-flex min-h-12 cursor-pointer items-center justify-center gap-2 rounded-xl border border-zinc-700 px-3 text-sm font-bold text-zinc-300"><input type="file" accept="image/*" className="hidden" onChange={(event) => selectPhoto(event.target.files?.[0])} /><ImagePlus size={18} /> Galería</label></div></div></div></div></div><div className="grid gap-3 sm:grid-cols-2"><label className="flex cursor-pointer items-start gap-3 rounded-2xl border border-violet-500/30 bg-violet-500/10 p-4"><input type="checkbox" name="solo_localizacion" disabled={Boolean(createdId)} className="mt-1 h-5 w-5 accent-violet-400" /><span><span className="block font-black text-violet-100">Solo localizar</span><span className="mt-1 block text-xs leading-5 text-violet-200/65">Se verá en el plano, pero nadie podrá retirarlo.</span></span></label><Field label="Espacio que ocupa"><input name="espacio_ocupado" disabled={Boolean(createdId)} className="input disabled:opacity-50" placeholder="Ej. caja azul, media balda..." /></Field></div><Field label="Descripción"><textarea name="descripcion" rows={3} disabled={Boolean(createdId)} className="input resize-none disabled:opacity-50" placeholder="Contenido del maletín o indicaciones de uso" /></Field><button disabled={saving} className="flex min-h-14 w-full items-center justify-center gap-2 rounded-xl bg-cyan-400 py-3 font-black text-zinc-950 disabled:opacity-50">{saving ? <Loader2 className="animate-spin" /> : createdId ? <Camera /> : <PackagePlus />} {savingText || (createdId ? "Reintentar guardar foto" : "Registrar herramienta")}</button></form></Modal>;
}

function EditToolModal({ tool, onClose, onSaved }: { tool: HerramientaComun; onClose: () => void; onSaved: () => void | Promise<void> }) {
  const [photo, setPhoto] = useState<File | null>(null); const [preview, setPreview] = useState(tool.foto_url || ""); const [localPreview, setLocalPreview] = useState(""); const [saving, setSaving] = useState(false); const [savingText, setSavingText] = useState(""); const [error, setError] = useState("");
  useEffect(() => () => { if (localPreview) URL.revokeObjectURL(localPreview); }, [localPreview]);
  function selectPhoto(file?: File) { setError(""); if (!file) return; if (!file.type.startsWith("image/") || file.size > PHOTO_SOURCE_MAX_BYTES) { setError("Selecciona una fotografía válida de hasta 30 MB."); return; } const objectUrl = URL.createObjectURL(file); setPhoto(file); setLocalPreview(objectUrl); setPreview(objectUrl); }
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setSaving(true); setError(""); const body = { ...Object.fromEntries(new FormData(event.currentTarget).entries()), action: "editar" }; try { setSavingText("Guardando cambios..."); const response = await fetch(`/api/herramientas-comunes/${tool.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error || "No se pudo editar la herramienta."); if (photo) { setSavingText("Preparando nueva fotografía..."); const optimized = await optimizePhoto(photo); setSavingText("Sustituyendo fotografía..."); const photoResponse = await fetch(`/api/herramientas-comunes/${tool.id}/foto`, { method: "POST", headers: { "Content-Type": optimized.type || "application/octet-stream", "X-Photo-Name": encodeURIComponent(optimized.name) }, body: optimized }); const photoPayload = await photoResponse.json() as { error?: string }; if (!photoResponse.ok) throw new Error(photoPayload.error || "Los datos se guardaron, pero no se pudo sustituir la fotografía."); } await onSaved(); } catch (caught) { setError(caught instanceof Error ? caught.message : "No se pudo editar la herramienta."); } finally { setSaving(false); setSavingText(""); } }
  return <Modal title="Editar herramienta" subtitle={`${tool.codigo} · ${tool.nombre}`} onClose={onClose}><form onSubmit={submit} className="space-y-4">{error && <Notice tone="red">{error}</Notice>}<div className="rounded-xl border border-zinc-700 bg-zinc-950/50 p-3 text-sm text-zinc-400"><strong className="text-white">Código automático:</strong> {tool.codigo}<br /><span className="text-xs">El código y la ubicación se gestionan con las etiquetas QR.</span></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre *"><input name="nombre" defaultValue={tool.nombre} required className="input" /></Field><Field label="Categoría"><input name="categoria" defaultValue={tool.categoria || ""} className="input" /></Field><Field label="Marca"><input name="marca" defaultValue={tool.marca || ""} className="input" /></Field><div><span className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-zinc-400">Fotografía</span><div className="flex items-center gap-3">{preview ? <img src={preview} alt="Fotografía de la herramienta" className="h-20 w-20 rounded-xl border border-zinc-700 object-cover" /> : <span className="flex h-20 w-20 items-center justify-center rounded-xl bg-zinc-950 text-zinc-700"><Camera /></span>}<label className="inline-flex min-h-12 cursor-pointer items-center gap-2 rounded-xl border border-cyan-500/30 bg-cyan-500/10 px-3 text-sm font-bold text-cyan-200"><input type="file" accept="image/*" capture="environment" className="hidden" onChange={(event) => selectPhoto(event.target.files?.[0])} /><Camera size={17} /> Cambiar foto</label></div></div></div><div className="grid gap-3 sm:grid-cols-2"><label className="flex cursor-pointer items-start gap-3 rounded-2xl border border-violet-500/30 bg-violet-500/10 p-4"><input type="checkbox" name="solo_localizacion" defaultChecked={tool.solo_localizacion} className="mt-1 h-5 w-5 accent-violet-400" /><span><span className="block font-black text-violet-100">Solo localizar</span><span className="mt-1 block text-xs leading-5 text-violet-200/65">Se verá en el plano, pero nadie podrá retirarlo.</span></span></label><Field label="Espacio que ocupa"><input name="espacio_ocupado" defaultValue={tool.espacio_ocupado || ""} className="input" placeholder="Ej. caja azul, media balda..." /></Field></div><Field label="Descripción"><textarea name="descripcion" rows={3} defaultValue={tool.descripcion || ""} className="input resize-none" /></Field><button disabled={saving} className="flex min-h-14 w-full items-center justify-center gap-2 rounded-xl bg-cyan-400 py-3 font-black text-zinc-950 disabled:opacity-50">{saving ? <Loader2 className="animate-spin" /> : <Edit3 />} {savingText || "Guardar cambios"}</button></form></Modal>;
}

function ScannedToolModal({ tool, busy, onClose, onLoan, onReturn, onPlace, onChoosePlan, onShowLocation }: { tool: HerramientaComun; busy: boolean; onClose: () => void; onLoan: () => void; onReturn: () => void; onPlace: () => void; onChoosePlan: () => void; onShowLocation: () => void }) {
  const located = Boolean(tool.estanteria_id && tool.nivel && tool.posicion);
  return <Modal title="Herramienta escaneada" subtitle={`${tool.codigo} · ${tool.nombre}`} onClose={onClose}><div className="space-y-4"><div className="flex items-start gap-4 rounded-2xl border border-zinc-700 bg-zinc-950/50 p-4">{tool.foto_url ? <img src={tool.foto_url} alt="" className="h-24 w-24 rounded-xl object-cover" /> : <span className="flex h-24 w-24 items-center justify-center rounded-xl bg-zinc-900 text-zinc-600"><Wrench size={36} /></span>}<div className="min-w-0"><span className="flex flex-wrap items-center gap-2"><StatusBadge status={tool.estado} /><ToolModeBadge tool={tool} /></span><h3 className="mt-3 text-xl font-black text-white">{tool.nombre}</h3>{tool.estado === "prestada" ? <p className="mt-2 font-bold text-amber-200">La tiene {tool.empleado_actual}{tool.vehiculo_actual ? ` · ${tool.vehiculo_actual}` : ""}</p> : <p className={`mt-2 text-sm font-bold ${located ? "text-cyan-100" : "text-red-200"}`}>{location(tool)}</p>}{tool.espacio_ocupado && <p className="mt-2 text-sm font-bold text-violet-200">Ocupa: {tool.espacio_ocupado}</p>}</div></div>{!located && <div className="space-y-3"><p className="text-center text-sm font-bold text-zinc-400">¿Cómo quieres elegir dónde guardarla?</p><button onClick={onPlace} className="flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl bg-emerald-400 text-lg font-black text-zinc-950"><ScanLine /> Escanear QR del hueco</button><button onClick={onChoosePlan} className="flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl border border-cyan-500/40 bg-cyan-500/10 text-lg font-black text-cyan-100"><LayoutGrid /> Elegir en el plano</button></div>}{tool.solo_localizacion && located && <div className="rounded-2xl border border-violet-500/30 bg-violet-500/10 p-4 text-sm font-bold text-violet-100">Material de solo localización · permanece en este sitio y no se puede retirar.</div>}{tool.estado === "disponible" && located && !tool.solo_localizacion && <button onClick={onLoan} className="flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl bg-cyan-400 text-lg font-black text-zinc-950"><Wrench /> Me la llevo</button>}{tool.estado === "prestada" && <button disabled={busy} onClick={onReturn} className="flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl bg-emerald-400 text-lg font-black text-zinc-950 disabled:opacity-50"><ScanLine /> Devolver escaneando su hueco</button>}{tool.estado !== "disponible" && tool.estado !== "prestada" && <Notice tone="red">Esta herramienta figura como {STATUS[tool.estado].label.toLocaleLowerCase("es")}.</Notice>}{located && <button onClick={onShowLocation} className="flex min-h-12 w-full items-center justify-center gap-2 rounded-xl border border-amber-500/30 font-bold text-amber-200"><MapPin size={18} /> Ver su sitio en el plano</button>}</div></Modal>;
}

type PlanSelection = { shelfId: number; level: number; position: string };

function UnlocatedToolsModal({ tools, onClose, onScan, onPlan }: { tools: HerramientaComun[]; onClose: () => void; onScan: (tool: HerramientaComun) => void; onPlan: (tool: HerramientaComun) => void }) {
  return <Modal title="Herramientas sin ubicación" subtitle={`${tools.length} pendiente${tools.length === 1 ? "" : "s"} de colocar`} onClose={onClose}><div className="space-y-3">{tools.length ? tools.map((tool) => <article key={tool.id} className="rounded-2xl border border-zinc-700 bg-zinc-950/55 p-3"><div className="flex items-center gap-3">{tool.foto_url ? <img src={tool.foto_url} alt="" className="h-14 w-14 shrink-0 rounded-xl object-cover" /> : <span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-xl bg-zinc-900 text-zinc-600"><Wrench size={24} /></span>}<div className="min-w-0"><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><h3 className="truncate font-black text-white">{tool.nombre}</h3>{tool.espacio_ocupado && <p className="truncate text-xs font-bold text-violet-200">Ocupa: {tool.espacio_ocupado}</p>}</div></div><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={() => onScan(tool)} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-emerald-400 px-2 text-sm font-black text-zinc-950"><ScanLine size={18} /> Escanear hueco</button><button onClick={() => onPlan(tool)} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-xl border border-cyan-500/35 bg-cyan-500/10 px-2 text-sm font-black text-cyan-100"><LayoutGrid size={18} /> Elegir plano</button></div></article>) : <div className="rounded-2xl border border-emerald-500/25 bg-emerald-500/10 px-5 py-12 text-center"><CheckCircle2 className="mx-auto text-emerald-300" size={42} /><p className="mt-3 font-black text-emerald-100">Todas tienen ubicación</p></div>}</div></Modal>;
}

function PlaceToolPlanModal({ tool, shelves, busy, onClose, onConfirm }: { tool: HerramientaComun; shelves: EstanteriaHerramientas[]; busy: boolean; onClose: () => void; onConfirm: (shelf: EstanteriaHerramientas, level: number, position: string) => void }) {
  const [selected, setSelected] = useState<PlanSelection | null>(null);
  const selectedShelf = selected ? shelves.find((shelf) => shelf.id === selected.shelfId) : undefined;
  const zones = Object.entries(Object.groupBy(shelves, (shelf) => shelf.zona));

  return <Modal wide title="Elegir ubicación en el plano" subtitle={`¿Dónde vas a guardar ${tool.nombre}?`} onClose={onClose}><div className="space-y-6">
    {!shelves.length && <Notice tone="red">No hay estanterías configuradas. Un administrador debe crear primero el plano.</Notice>}
    {zones.map(([zone, zoneShelves]) => <section key={zone} className="space-y-3"><header className="flex items-center gap-2"><MapPin className="text-cyan-300" size={20} /><h3 className="text-lg font-black uppercase tracking-wide text-white">{zone}</h3></header><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{zoneShelves?.map((shelf) => {
      const rows = shelf.configuracion?.filas?.length ? shelf.configuracion.filas : fallbackRows(shelf.niveles);
      return <article key={shelf.id} className="overflow-hidden rounded-2xl border border-zinc-700 bg-zinc-950/60"><header className="border-b border-zinc-800 bg-zinc-900 px-4 py-3"><p className="font-mono text-xs font-black text-cyan-300">{shelf.codigo}</p><p className="font-black text-white">{shelf.nombre}</p></header><div className="space-y-1.5 p-3">{rows.map((row) => <div key={row.nivel} className="grid gap-1.5" style={{ gridTemplateColumns: `repeat(${row.columnas}, minmax(0, 1fr))` }}>{Array.from({ length: row.columnas }, (_, index) => {
        const position = `C${index + 1}`;
        const active = selected?.shelfId === shelf.id && selected.level === row.nivel && selected.position === position;
        const label = row.columnas > 1 ? `${row.nombre} · ${index + 1}` : row.nombre;
        return <button key={position} type="button" aria-pressed={active} onClick={() => setSelected({ shelfId: shelf.id, level: row.nivel, position })} className={`flex min-h-14 items-center justify-center gap-1 rounded-lg border px-1.5 py-2 text-center text-xs font-black transition ${active ? "border-emerald-300 bg-emerald-400 text-zinc-950 ring-2 ring-emerald-300/40" : row.tipo === "colgador" ? "border-amber-500/35 bg-amber-500/10 text-amber-100" : "border-zinc-700 bg-zinc-900 text-zinc-200 hover:border-cyan-400"}`}>{row.tipo === "colgador" && <Grip size={14} className="shrink-0" />}<span>{label}</span></button>;
      })}</div>)}</div></article>;
    })}</div></section>)}
    <div className="sticky bottom-0 -mx-5 border-t border-zinc-700 bg-zinc-900/95 px-5 pb-1 pt-4 backdrop-blur"><div className="mb-3 rounded-xl border border-cyan-500/25 bg-cyan-500/10 p-3"><p className="text-[10px] font-black uppercase tracking-wide text-cyan-300">Ubicación elegida</p><p className="mt-1 font-black text-white">{selected && selectedShelf ? locationName(selectedShelf, selected.level, selected.position) : "Pulsa un hueco del plano"}</p></div><button disabled={busy || !selected || !selectedShelf} onClick={() => selected && selectedShelf && onConfirm(selectedShelf, selected.level, selected.position)} className="flex min-h-14 w-full items-center justify-center gap-2 rounded-xl bg-emerald-400 px-4 font-black text-zinc-950 disabled:cursor-not-allowed disabled:opacity-40">{busy ? <Loader2 className="animate-spin" /> : <CheckCircle2 />} Confirmar y colocar aquí</button></div>
  </div></Modal>;
}

function ScannedLocationModal({ value, tools, returningTool, onClose, onRetry }: { value: ScannedLocation; tools: HerramientaComun[]; returningTool: HerramientaComun | null; onClose: () => void; onRetry: () => void }) {
  const scannedName = locationName(value.shelf, value.level, value.position);
  if (returningTool) return <Modal title="Ese no es su hueco" subtitle={returningTool.nombre} onClose={onClose}><div className="space-y-4"><div className="rounded-2xl border border-red-500/30 bg-red-500/10 p-5"><AlertTriangle className="mb-3 text-red-300" size={34} /><p className="font-black text-red-100">No se ha registrado la devolución</p><p className="mt-2 text-sm text-red-200/70">Has escaneado: <strong>{scannedName}</strong></p></div><div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-4"><p className="text-xs font-bold uppercase text-emerald-300">Su ubicación correcta</p><p className="mt-1 font-black text-emerald-100">{location(returningTool)}</p></div><button onClick={onRetry} className="flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl bg-cyan-400 text-lg font-black text-zinc-950"><ScanLine /> Escanear el hueco correcto</button></div></Modal>;
  return <Modal title="Ubicación escaneada" subtitle={scannedName} onClose={onClose}><div className="space-y-4"><div className="rounded-2xl border border-cyan-500/30 bg-cyan-500/10 p-4"><p className="text-xs font-bold uppercase text-cyan-300">Aquí deben guardarse</p><p className="mt-1 text-2xl font-black text-white">{tools.length} herramienta{tools.length === 1 ? "" : "s"}</p></div>{tools.length ? <div className="space-y-2">{tools.map((tool) => <div key={tool.id} className="flex items-center justify-between gap-3 rounded-xl border border-zinc-800 bg-zinc-950/50 p-3"><div><p className="font-mono text-[10px] font-black text-cyan-300">{tool.codigo}</p><p className="font-bold text-white">{tool.nombre}</p></div><StatusBadge status={tool.estado} /></div>)}</div> : <Empty text="Este hueco no tiene herramientas asignadas." />}</div></Modal>;
}

function LabelsModal({ tools, shelves, onClose }: { tools: HerramientaComun[]; shelves: EstanteriaHerramientas[]; onClose: () => void }) {
  const [query, setQuery] = useState("");
  const term = normalize(query);
  const filteredTools = term ? tools.filter((tool) => normalize([tool.codigo, tool.nombre, tool.marca, tool.categoria, tool.descripcion, tool.estanteria?.codigo, tool.estanteria?.nombre, tool.estanteria?.zona].filter(Boolean).join(" ")).includes(term)) : tools;
  return <Modal wide title="Etiquetas QR" subtitle="Imprime las herramientas y todos los huecos de cada estantería" onClose={onClose}><div className="grid gap-6 lg:grid-cols-2"><section><h3 className="mb-3 flex items-center gap-2 text-lg font-black"><Wrench className="text-cyan-300" /> Herramientas</h3><label className="relative mb-3 block"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-cyan-400" size={19} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar nombre, código, marca..." className="input !py-3 !pl-10 !pr-10" />{query && <button type="button" onClick={() => setQuery("")} aria-label="Limpiar búsqueda" className="absolute right-2 top-1/2 -translate-y-1/2 rounded-lg p-2 text-zinc-400 hover:bg-zinc-800"><X size={17} /></button>}</label><p className="mb-2 text-xs font-bold text-zinc-500">{filteredTools.length} de {tools.length} herramientas</p><div className="max-h-[50dvh] space-y-2 overflow-y-auto pr-1">{filteredTools.length ? filteredTools.map((tool) => <div key={tool.id} className="flex flex-col gap-2 rounded-xl border border-zinc-800 bg-zinc-950/50 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-mono text-xs font-black text-cyan-300">{tool.codigo}</p><p className="font-bold text-white">{tool.nombre}</p></div><ToolQrLabelButton tool={tool} /></div>) : <div className="rounded-xl border border-dashed border-zinc-700 px-4 py-10 text-center text-sm text-zinc-500">No hay herramientas que coincidan con la búsqueda.</div>}</div></section><section><h3 className="mb-3 flex items-center gap-2 text-lg font-black"><LayoutGrid className="text-amber-300" /> Huecos de estanterías</h3><div className="space-y-3">{shelves.map((shelf) => <div key={shelf.id} className="rounded-xl border border-zinc-800 bg-zinc-950/50 p-4"><p className="font-mono text-xs font-black text-amber-300">{shelf.codigo}</p><p className="mb-3 font-bold text-white">{shelf.zona} · {shelf.nombre} · {shelf.configuracion.filas.reduce((sum, row) => sum + row.columnas, 0)} etiquetas</p><ShelfLocationLabelsButton shelf={shelf} /></div>)}</div></section></div></Modal>;
}

function ToolLabelAfterSaveModal({ tool, onClose }: { tool: HerramientaComun; onClose: () => void }) {
  return <Modal title="Herramienta guardada" subtitle={`${tool.codigo} · ${tool.nombre}`} onClose={onClose}><div className="space-y-4"><div className="rounded-2xl border border-emerald-500/25 bg-emerald-500/10 p-5"><CheckCircle2 className="mb-3 text-emerald-300" size={34} /><p className="font-black text-emerald-100">Los datos se han guardado correctamente</p><p className="mt-1 text-sm text-emerald-200/60">Si necesitas identificarla ahora, puedes imprimir su etiqueta QR.</p></div><ToolQrLabelButton tool={tool} /><button onClick={onClose} className="min-h-12 w-full rounded-xl border border-zinc-700 font-bold text-zinc-300">Terminar sin imprimir</button></div></Modal>;
}

type ShelfDraft = { id?: number; codigo: string; nombre: string; zona: string; configuracion: ConfiguracionEstanteriaHerramientas };

function ShelfManager({ shelves, onClose, onChanged }: { shelves: EstanteriaHerramientas[]; onClose: () => void; onChanged: () => void | Promise<void> }) {
  const [draft, setDraft] = useState<ShelfDraft>(() => shelfDraft(shelves[0]));
  const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [success, setSuccess] = useState("");
  const updateRow = (index: number, patch: Partial<FilaEstanteriaHerramientas>) => setDraft((current) => ({ ...current, configuracion: { filas: current.configuracion.filas.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row) } }));
  const moveRow = (index: number, direction: -1 | 1) => setDraft((current) => { const rows = [...current.configuracion.filas]; const target = index + direction; if (target < 0 || target >= rows.length) return current; [rows[index], rows[target]] = [rows[target], rows[index]]; return { ...current, configuracion: { filas: rows } }; });
  async function save() { setSaving(true); setError(""); setSuccess(""); try { const response = await fetch(draft.id ? `/api/herramientas-comunes/estanterias/${draft.id}` : "/api/herramientas-comunes/estanterias", { method: draft.id ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft) }); const payload = await response.json() as EstanteriaHerramientas & { error?: string }; if (!response.ok) throw new Error(payload.error || "No se pudo guardar la estantería."); await onChanged(); setDraft(shelfDraft(payload)); setSuccess("Estantería guardada."); } catch (caught) { setError(caught instanceof Error ? caught.message : "No se pudo guardar la estantería."); } finally { setSaving(false); } }
  async function remove() { if (!draft.id || !window.confirm("¿Retirar esta estantería del plano?")) return; setSaving(true); setError(""); try { const response = await fetch(`/api/herramientas-comunes/estanterias/${draft.id}`, { method: "DELETE" }); const payload = await response.json() as { error?: string }; if (!response.ok) throw new Error(payload.error || "No se pudo retirar."); await onChanged(); const remaining = shelves.filter((item) => item.id !== draft.id); setDraft(shelfDraft(remaining[0])); setSuccess("Estantería retirada del plano."); } catch (caught) { setError(caught instanceof Error ? caught.message : "No se pudo retirar."); } finally { setSaving(false); } }
  return <Modal wide title="Configurar estanterías" subtitle="Puedes cambiar el plano sin tocar la base de datos" onClose={onClose}><div className="grid gap-5 lg:grid-cols-[240px_1fr]"><aside className="space-y-2"><button onClick={() => { setDraft(shelfDraft()); setError(""); setSuccess(""); }} className="flex w-full items-center justify-center gap-2 rounded-xl border border-cyan-500/30 bg-cyan-500/10 p-3 font-bold text-cyan-300"><Plus size={17} /> Nueva estantería</button>{shelves.map((shelf) => <button key={shelf.id} onClick={() => { setDraft(shelfDraft(shelf)); setError(""); setSuccess(""); }} className={`w-full rounded-xl border p-3 text-left ${draft.id === shelf.id ? "border-cyan-400 bg-cyan-500/10" : "border-zinc-800 bg-zinc-950/50"}`}><span className="font-mono text-xs font-black text-cyan-300">{shelf.codigo}</span><span className="block font-bold">{shelf.nombre}</span><span className="text-xs text-zinc-500">{shelf.zona} · {shelf.configuracion?.filas?.length || shelf.niveles} filas</span></button>)}</aside><section className="space-y-4">{error && <Notice tone="red">{error}</Notice>}{success && <Notice tone="green">{success}</Notice>}<div className="grid gap-3 sm:grid-cols-3"><Field label="Código"><input value={draft.codigo} onChange={(event) => setDraft((current) => ({ ...current, codigo: event.target.value.toUpperCase() }))} className="input" placeholder="T01" /></Field><Field label="Nombre"><input value={draft.nombre} onChange={(event) => setDraft((current) => ({ ...current, nombre: event.target.value }))} className="input" /></Field><Field label="Zona"><input value={draft.zona} onChange={(event) => setDraft((current) => ({ ...current, zona: event.target.value }))} className="input" placeholder="Taller" /></Field></div><div><div className="mb-2 flex items-center justify-between"><div><h3 className="font-black">Filas, de arriba hacia abajo</h3><p className="text-xs text-zinc-500">Añade divisiones verticales cuando una fila tenga varios huecos.</p></div><button onClick={() => setDraft((current) => ({ ...current, configuracion: { filas: [...current.configuracion.filas, { nivel: 1, nombre: `Nivel ${current.configuracion.filas.length + 1}`, tipo: "balda", columnas: 1, altura: 1 }] } }))} className="action action-primary"><Plus size={15} /> Fila</button></div><div className="space-y-2">{draft.configuracion.filas.map((row, index) => <div key={index} className="grid gap-2 rounded-xl border border-zinc-800 bg-zinc-950/45 p-3 sm:grid-cols-[auto_1fr_130px_100px_90px_auto]"><div className="flex sm:flex-col"><button disabled={index === 0} onClick={() => moveRow(index, -1)} className="p-1 text-zinc-500 disabled:opacity-20"><ArrowUp size={16} /></button><button disabled={index === draft.configuracion.filas.length - 1} onClick={() => moveRow(index, 1)} className="p-1 text-zinc-500 disabled:opacity-20"><ArrowDown size={16} /></button></div><input value={row.nombre} onChange={(event) => updateRow(index, { nombre: event.target.value })} className="input !py-2" aria-label="Nombre de la fila" /><select value={row.tipo} onChange={(event) => updateRow(index, { tipo: event.target.value as FilaEstanteriaHerramientas["tipo"] })} className="input !py-2"><option value="balda">Balda</option><option value="colgador">Colgador</option></select><label className="text-[10px] font-bold uppercase text-zinc-500">Divisiones<input type="number" min="1" max="12" value={row.columnas} onChange={(event) => updateRow(index, { columnas: Number(event.target.value) })} className="input mt-1 !py-1.5" /></label><label className="text-[10px] font-bold uppercase text-zinc-500">Altura<input type="number" min="1" max="4" value={row.altura} onChange={(event) => updateRow(index, { altura: Number(event.target.value) })} className="input mt-1 !py-1.5" /></label><button disabled={draft.configuracion.filas.length === 1} onClick={() => setDraft((current) => ({ ...current, configuracion: { filas: current.configuracion.filas.filter((_, rowIndex) => rowIndex !== index) } }))} className="self-center justify-self-end rounded-lg p-2 text-red-300 hover:bg-red-500/10 disabled:opacity-20" title="Eliminar fila"><Trash2 size={17} /></button></div>)}</div></div><div className="flex flex-col-reverse gap-2 border-t border-zinc-800 pt-4 sm:flex-row sm:justify-between">{draft.id ? <button disabled={saving} onClick={() => void remove()} className="inline-flex items-center justify-center gap-2 rounded-xl border border-red-500/30 px-4 py-3 font-bold text-red-300"><Trash2 size={17} /> Retirar estantería</button> : <span />}<button disabled={saving || !draft.configuracion.filas.length} onClick={() => void save()} className="inline-flex items-center justify-center gap-2 rounded-xl bg-cyan-400 px-5 py-3 font-black text-zinc-950 disabled:opacity-50">{saving ? <Loader2 className="animate-spin" size={18} /> : <Settings size={18} />} Guardar plano</button></div></section></div></Modal>;
}

function LoanModal({ tool, currentUser, actionUsers, actionUsersLoading, askVehicle, requireVehicle, busy, onClose, onConfirm }: { tool: HerramientaComun; currentUser: AppUser | null; actionUsers: AppUser[]; actionUsersLoading: boolean; askVehicle: boolean; requireVehicle: boolean; busy: boolean; onClose: () => void; onConfirm: (vehicle: string, actorUserId: string, actorName: string) => void }) {
  const [vehicle, setVehicle] = useState(""); const [actorUserId, setActorUserId] = useState("");
  const actorName = currentUser?.rol === "administrador" ? actionUsers.find((user) => user.id === actorUserId)?.nombre || "" : currentUser?.nombre || "";
  return <Modal title="Retirar herramienta" subtitle={tool.nombre} onClose={onClose}><div className="space-y-4"><ActionActorSelect currentUser={currentUser} users={actionUsers} loading={actionUsersLoading} value={actorUserId} onChange={setActorUserId} label="Empleado que retira la herramienta" /><div className="rounded-xl border border-amber-500/20 bg-amber-500/10 p-4 text-sm text-amber-100"><p><strong>Lugar de devolución:</strong> {location(tool)}</p></div>{askVehicle && <Field label={requireVehicle ? "Vehículo *" : "Vehículo (opcional)"}><input value={vehicle} onChange={(event) => setVehicle(event.target.value)} className="input" placeholder="Matrícula, modelo u orden de trabajo" /></Field>}<button disabled={busy || actionUsersLoading || (currentUser?.rol === "administrador" && !actorUserId) || (requireVehicle && !vehicle.trim())} onClick={() => onConfirm(vehicle, actorUserId, actorName)} className="flex min-h-14 w-full items-center justify-center gap-2 rounded-xl bg-amber-400 py-3 font-black text-zinc-950 disabled:opacity-50">{busy ? <Loader2 className="animate-spin" /> : <Wrench />} Confirmar retirada</button></div></Modal>;
}

function LocationModal({ tool, shelves, busy, onClose, onConfirm }: { tool: HerramientaComun; shelves: EstanteriaHerramientas[]; busy: boolean; onClose: () => void; onConfirm: (shelfId: number, level: number, position: string) => void }) {
  const [shelfId, setShelfId] = useState(tool.estanteria_id || shelves[0]?.id || 0); const [level, setLevel] = useState(tool.nivel || shelves[0]?.configuracion?.filas?.[0]?.nivel || 1);
  const shelf = shelves.find((item) => item.id === shelfId) || shelves[0]; const rows = shelf?.configuracion?.filas || []; const selectedLevel = rows.some((row) => row.nivel === level) ? level : rows[0]?.nivel || 1; const row = rows.find((item) => item.nivel === selectedLevel); const [position, setPosition] = useState(normalizePosition(tool.posicion)); const selectedPosition = Number(position.slice(1)) <= (row?.columnas || 1) ? position : "C1";
  return <Modal title="Cambiar ubicación" subtitle={tool.nombre} onClose={onClose}><div className="space-y-4"><div className="rounded-xl border border-zinc-700 bg-zinc-950/50 p-3 text-sm text-zinc-400"><strong className="text-white">Ubicación actual:</strong> {location(tool)}</div><Field label="Estantería"><select value={shelf?.id || ""} onChange={(event) => { const next = Number(event.target.value); setShelfId(next); const nextShelf = shelves.find((item) => item.id === next); setLevel(nextShelf?.configuracion?.filas?.[0]?.nivel || 1); setPosition("C1"); }} className="input">{shelves.map((item) => <option key={item.id} value={item.id}>{item.zona} · {item.codigo} · {item.nombre}</option>)}</select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Nivel o zona"><select value={selectedLevel} onChange={(event) => { setLevel(Number(event.target.value)); setPosition("C1"); }} className="input">{rows.map((item) => <option key={item.nivel} value={item.nivel}>{item.nombre}{item.tipo === "colgador" ? " · colgador" : ""}</option>)}</select></Field><Field label="Compartimento"><select value={selectedPosition} onChange={(event) => setPosition(event.target.value)} className="input">{Array.from({ length: row?.columnas || 1 }, (_, index) => <option key={index} value={`C${index + 1}`}>{row && row.columnas > 1 ? `Compartimento ${index + 1}` : "Espacio completo"}</option>)}</select></Field></div><button disabled={busy || !shelf} onClick={() => shelf && onConfirm(shelf.id, selectedLevel, selectedPosition)} className="flex w-full items-center justify-center gap-2 rounded-xl bg-cyan-400 py-3 font-black text-zinc-950 disabled:opacity-50">{busy ? <Loader2 className="animate-spin" /> : <MapPin />} Guardar nueva ubicación</button></div></Modal>;
}

function HistoryModal({ tool, movements, onClose }: { tool: HerramientaComun; movements: MovimientoHerramienta[]; onClose: () => void }) {
  const photos = tool.fotos || [];
  const initialPhoto = photos.find((photo) => photo.tipo === "inicial");
  const currentPhoto = photos.at(-1);
  return <Modal title="Historial de movimientos" subtitle={`${tool.codigo} · ${tool.nombre}`} onClose={onClose}><div className="space-y-5">{initialPhoto && <section><h3 className="mb-2 text-sm font-black text-white">Estado fotográfico</h3><div className="grid grid-cols-2 gap-3"><PhotoSnapshot title="Foto inicial" url={initialPhoto.url} date={initialPhoto.created_at} />{currentPhoto && currentPhoto.id !== initialPhoto.id && <PhotoSnapshot title="Foto más reciente" url={currentPhoto.url} date={currentPhoto.created_at} />}</div>{photos.length > 2 && <p className="mt-2 text-xs text-zinc-500">Se conservan {photos.length} fotografías en total.</p>}</section>}{movements.length ? <div className="space-y-3">{movements.map((item) => <div key={item.id} className={`rounded-xl border p-4 ${item.tipo === "retirada" ? "border-amber-500/25 bg-amber-500/5" : item.tipo === "devolucion" ? "border-emerald-500/25 bg-emerald-500/5" : "border-zinc-800 bg-zinc-950/50"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><MovementBadge type={item.tipo} /><p className="font-bold text-white">{movementLabel(item)}</p></div>{item.vehiculo && <p className="mt-2 text-sm text-zinc-400">Vehículo: {item.vehiculo}</p>}{item.detalle && <p className="mt-1 text-xs text-zinc-600">{item.detalle}</p>}</div><span className="whitespace-nowrap text-xs text-zinc-600">{formatDate(item.created_at)}</span></div></div>)}</div> : <Empty text="Todavía no hay movimientos." />}</div></Modal>;
}

function PhotoSnapshot({ title, url, date }: { title: string; url: string; date: string }) {
  return <figure className="overflow-hidden rounded-xl border border-zinc-700 bg-zinc-950"><img src={url} alt={title} className="aspect-square w-full object-cover" /><figcaption className="p-2"><p className="text-xs font-black text-white">{title}</p><p className="text-[10px] text-zinc-500">{formatDate(date)}</p></figcaption></figure>;
}

function PhotoPreview({ url, alt, onClose }: { url: string; alt: string; onClose: () => void }) {
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", closeOnEscape);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", closeOnEscape);
    };
  }, [onClose]);
  return <div onClick={(event) => event.stopPropagation()} className="fixed inset-0 z-[100] flex items-center justify-center p-3 sm:p-8"><button type="button" aria-label="Cerrar fotografía" onClick={onClose} className="absolute inset-0 bg-black/95" /><div className="relative z-10 flex max-h-full max-w-full items-center justify-center"><img src={url} alt={alt} className="max-h-[92dvh] max-w-[94vw] rounded-2xl object-contain shadow-2xl" /><button type="button" onClick={onClose} className="absolute right-2 top-2 rounded-full border border-white/20 bg-black/75 p-3 text-white shadow-xl" aria-label="Cerrar"><X size={24} /></button></div></div>;
}

function Modal({ title, subtitle, onClose, children, wide = false }: { title: string; subtitle?: string; onClose: () => void; children: ReactNode; wide?: boolean }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/85 backdrop-blur-sm sm:items-center sm:p-4"><div className={`flex max-h-[96dvh] w-full flex-col overflow-hidden rounded-t-3xl border border-zinc-700 bg-zinc-900 shadow-2xl sm:rounded-3xl ${wide ? "max-w-6xl" : "max-w-2xl"}`}><header className="flex items-start justify-between border-b border-zinc-800 p-5"><div><h2 className="text-xl font-black">{title}</h2>{subtitle && <p className="mt-1 text-sm text-zinc-500">{subtitle}</p>}</div><button onClick={onClose} className="rounded-xl p-2 text-zinc-400 hover:bg-zinc-800"><X /></button></header><div className="overflow-y-auto p-5">{children}</div></div></div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block"><span className="mb-1.5 block text-xs font-bold uppercase tracking-wide text-zinc-400">{label}</span>{children}</label>; }
function StatusBadge({ status }: { status: EstadoHerramienta }) { const item = STATUS[status]; return <span className={`rounded-full border px-2.5 py-1 text-xs font-black ${item.classes}`}>{item.label}</span>; }
function ToolModeBadge({ tool }: { tool: HerramientaComun }) { return tool.solo_localizacion ? <span className="rounded-full border border-violet-500/30 bg-violet-500/10 px-2.5 py-1 text-xs font-black text-violet-200">Solo localizar</span> : null; }
function Summary({ label, value, tone }: { label: string; value: number; tone: "cyan" | "emerald" | "amber" }) { const colors = { cyan: "border-cyan-500/20 text-cyan-300", emerald: "border-emerald-500/20 text-emerald-300", amber: "border-amber-500/20 text-amber-300" }; return <div className={`rounded-xl border bg-zinc-900/80 p-3 text-center sm:rounded-2xl sm:p-4 ${colors[tone]}`}><p className="text-[10px] font-bold uppercase sm:text-xs">{label}</p><p className="mt-1 text-2xl font-black text-white">{value}</p></div>; }
function Notice({ tone, children }: { tone: "red" | "green"; children: ReactNode }) { return <div className={`rounded-xl border p-4 text-sm ${tone === "red" ? "border-red-500/30 bg-red-500/10 text-red-200" : "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"}`}>{children}</div>; }
function ViewButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: ReactNode }) { return <button onClick={onClick} className={`flex items-center justify-center gap-1 rounded-lg px-3 py-2 text-sm font-bold ${active ? "bg-zinc-700 text-white" : "text-zinc-500"}`}>{children}</button>; }
function Empty({ text = "No hay herramientas que coincidan con la búsqueda." }: { text?: string }) { return <div className="rounded-2xl border border-dashed border-zinc-700 py-16 text-center text-zinc-500"><Wrench className="mx-auto mb-3 text-zinc-700" size={42} /><p>{text}</p></div>; }
function normalize(value: string) { return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("es").trim(); }
function location(tool: HerramientaComun) { if (!tool.estanteria_id || !tool.nivel || !tool.posicion || !tool.estanteria) return "Sin ubicación asignada"; const row = tool.estanteria.configuracion?.filas?.find((item) => item.nivel === tool.nivel); const position = normalizePosition(tool.posicion); return `${tool.estanteria.zona} · ${tool.estanteria.codigo} · ${row?.nombre || `nivel ${tool.nivel}`}${row && row.columnas > 1 ? ` · compartimento ${position.slice(1)}` : ""}`; }
function locationName(shelf: EstanteriaHerramientas, level: number, position: string) { const row = shelf.configuracion.filas.find((item) => item.nivel === level); return `${shelf.zona} · ${shelf.codigo} · ${row?.nombre || `nivel ${level}`}${row && row.columnas > 1 ? ` · compartimento ${normalizePosition(position).slice(1)}` : ""}`; }
function formatDate(value: string | null) { return value ? new Date(value).toLocaleString("es-ES", { dateStyle: "short", timeStyle: "short" }) : ""; }
function MovementBadge({ type }: { type: MovimientoHerramienta["tipo"] }) { if (type === "retirada") return <span className="rounded-full bg-amber-400 px-2.5 py-1 text-[10px] font-black text-zinc-950">RETIRÓ</span>; if (type === "devolucion") return <span className="rounded-full bg-emerald-400 px-2.5 py-1 text-[10px] font-black text-zinc-950">COLOCÓ</span>; return null; }
function movementLabel(item: MovimientoHerramienta) { if (item.tipo === "retirada") return `${item.empleado || "Empleado sin indicar"} retiró la herramienta`; if (item.tipo === "devolucion") return `${item.empleado || "Empleado sin indicar"} colocó la herramienta en su sitio`; return ({ alta: "Herramienta registrada", cambio_estado: "Estado actualizado", cambio_ubicacion: "Ubicación actualizada" })[item.tipo]; }
function fallbackRows(levels: number): FilaEstanteriaHerramientas[] { return Array.from({ length: levels }, (_, index) => ({ nivel: levels - index, nombre: `Nivel ${levels - index}`, tipo: "balda", columnas: 1, altura: 1 })); }
function normalizePosition(value: string | null | undefined) { const match = /^C(\d+)$/i.exec(value || ""); return match ? `C${Number(match[1])}` : "C1"; }
function shelfDraft(shelf?: EstanteriaHerramientas): ShelfDraft { return shelf ? { id: shelf.id, codigo: shelf.codigo, nombre: shelf.nombre, zona: shelf.zona, configuracion: { filas: (shelf.configuracion?.filas?.length ? shelf.configuracion.filas : fallbackRows(shelf.niveles)).map((row) => ({ ...row })) } } : { codigo: "", nombre: "Nueva estantería", zona: "Taller", configuracion: { filas: [{ nivel: 1, nombre: "Nivel 1", tipo: "balda", columnas: 1, altura: 1 }] } }; }
